//
// Browser-importable runtime placement for the e1-drive power-up slice.
//
// Contract:
//   import { RUNTIME_PLACEMENT_SCHEMA, placementsFor } from './runtime-placement.mjs';
//   const set = placementsFor('amboy');         // or 'gracia' / 'river'
//   const lap = placementsFor('river', 'lap');  // river also accepts '310m'
//
// `pickups[].x/y/z` are the retail `PickupPosition.WorldMatrix.aw` world
// coordinates. The measured-course arc/lateral projection is recorded in
// `source` and is never applied to the coordinate. `respawnSeconds === null`
// means the retail `Normal` timer is not serialized; the host must supply its
// own value and label it. `unsupported[]` carries the retail record id, type
// and typed reason.

export const RUNTIME_PLACEMENT_SCHEMA = 'blur-powerups-runtime-placement/1';

const MAP_LAYOUTS = Object.freeze({
  amboy: Object.freeze(['amboy']),
  gracia: Object.freeze(['gracia']),
  river: Object.freeze(['310m', 'lap'])
});

function deepFreeze(value) {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const key of Object.keys(value)) deepFreeze(value[key]);
  }
  return value;
}

function fail(message) {
  throw new Error('runtime-placement: ' + message);
}

function pickupSource(map, pickup, projection, layout) {
  const respawn = pickup.respawnSeconds === null
    ? 'respawn ' + pickup.respawnLabel + ' (not-serialized)'
    : 'respawn ' + pickup.respawnLabel + ' (' + pickup.respawnSeconds.toFixed(6) +
      ' s from MultiplayerConfig)';
  return 'retail PickupPosition uid ' + pickup.uid +
    ' (actorpack record ' + pickup.actorListRecord + ', route ' + map.routeRecordId + '); ' +
    'CourseModel.project nearest-segment arc/lateral projection on layout ' + layout + ': ' +
    'arc ' + projection.arc.toFixed(6) + ' m, ' +
    'lateral ' + projection.lateral.toFixed(6) + ' m, ' +
    'distance ' + projection.distance.toFixed(6) + ' m, ' +
    (projection.clamped ? 'endpoint-clamped' : 'interior') + '; ' +
    'xyz = retail WorldMatrix.aw; ' + respawn;
}

export const RUNTIME_PLACEMENT_DATA = deepFreeze(/*__RUNTIME_PLACEMENT_DATA__*/);

/**
 * Return the retail pickup placement set for a map and measured layout.
 *
 * @param {'amboy'|'gracia'|'river'} mapId
 * @param {'amboy'|'gracia'|'310m'|'lap'} [layout] river defaults to '310m'
 * @returns {{schema:string, mapId:string, source:string,
 *   pickups:Array<{id:string,type:string,x:number,y:number,z:number,
 *     respawnSeconds:number|null,lapMin:number,lapMax:number,source:string}>,
 *   unsupported:Array<{id:string,type:string,reason:string}>}}
 */
export function placementsFor(mapId, layout) {
  const map = RUNTIME_PLACEMENT_DATA.maps[mapId];
  if (!map) {
    fail('unknown map ' + JSON.stringify(mapId) + ' (use ' +
      Object.keys(RUNTIME_PLACEMENT_DATA.maps).join(', ') + ')');
  }
  const layouts = MAP_LAYOUTS[mapId];
  const selected = layout === undefined || layout === null ? map.defaultLayout : layout;
  if (!layouts.includes(selected)) {
    fail('unsupported layout ' + JSON.stringify(selected) + ' for ' + mapId +
      ' (use ' + layouts.join(', ') + ')');
  }
  const pickups = map.pickups.map((pickup) => {
    const projection = pickup.projections[selected];
    if (!projection) fail('pickup ' + pickup.id + ' has no ' + selected + ' projection');
    return {
      id: pickup.id,
      type: pickup.type,
      x: pickup.x,
      y: pickup.y,
      z: pickup.z,
      respawnSeconds: pickup.respawnSeconds,
      lapMin: pickup.activationLap > 0 ? pickup.activationLap : 0,
      lapMax: pickup.activationLap > 0 ? pickup.activationLap : map.laps[selected],
      source: pickupSource(map, pickup, projection, selected)
    };
  });
  return {
    schema: RUNTIME_PLACEMENT_SCHEMA,
    mapId,
    source: map.source + (map.defaultLayout === selected ? '' : '; layout ' + selected),
    pickups,
    unsupported: map.unsupported.map((row) => ({
      id: row.id,
      type: row.type,
      reason: row.reason
    }))
  };
}
